class MyHomePage extends StatefulWidget {
  @override
  _MyHomePageState createState() => _MyHomePageState();
}

class _MyHomePageState extends State<MyHomePage> {
  final GlobalKey<FormState> formKey = GlobalKey<FormState>();
  String value = '';
  bool submitEnabled = false;

  void _submit() async {
    if (!formKey.currentState!.validate()) {
      return;
    }

    setState(() {
      submitEnabled = true;
    });

    // 这是一个模拟的API调用或数据处理过程
    await Future.delayed(Duration(seconds: 1));
    setState(() {
      submitEnabled = false;
    });
  }

  @override
  Widget build(BuildContext context) {
    return Scaffold(
      appBar: AppBar(title: Text('Halal Validation')),
      body: Padding(
        padding: const EdgeInsets.all(16),
        child: Form(
          key: formKey,
          child: Column(
            children: [
              TextFormField(
                decoration: InputDecoration(labelText: 'Search Halal Products'),
                keyboardType: TextInputType.text,
                onFieldSubmitted: (value) {
                  if (value.isNotEmpty) {
                    setState(() {
                      value = value.trim();
                    });
                  } else {
                    setState(() {
                      value = '';
                    });
                  }
                },
                onChanged: (value) {
                  setState(() {
                    value = value.trim();
                  });
                },
                validator: (val) => val == null || val.isEmpty ? 'Enter search term' : null,
              ),
              SizedBox(height: 20),
              ElevatedButton(
                onPressed: () => _submit(),
                style: ButtonStyle(
                  backgroundColor: MaterialStateProperty.resolveWith((states) {
                    if (submitEnabled) return Color.fromRGBO(48, 134, 255, 0.8);
                    return Colors.blue;
                  }),
                ),
                child: Text(submitEnabled ? 'Loading...' : 'Submit'),
              ),
            ],
          ),
        ),
      ),
    );
  }
}
