class MyHomePage extends StatefulWidget {
  final String title;

  MyHomePage({required this.title});

  @override
  _MyHomePageState createState() => _MyHomePageState();
}

class _MyHomePageState extends State<MyHomePage> {
  late Timer _timer;

  void _startTimer() {
    _timer = Timer.periodic(Duration(seconds: 1), (timer) {
      setState(() {});
    });
  }

  void _stopTimer() {
    _timer.cancel();
  }

  bool _showResult = false;

  // Replace these constants with values from your database or API
  final List<String> questions = [
    "Q1: What do we use to wash our hands?",
    "Q2: Who said 'I'm not afraid of dogs'",
    "Q3: Which animal is the fastest?",
    "Q4: Which is India's national animal?"
  ];

  final List<String> answers = [
    "soap",
    "I'm not afraid of dogs",
    "lion",
    "tiger"
  ];

  @override
  void initState() {
    super.initState();
    _startTimer();
  }

  @override
  void dispose() {
    _stopTimer();
    super.dispose();
  }

  void _handleButtonPress(int index) {
    if (_showResult) return; // Prevent multiple selections

    if (index >= answers.length) {
      // Handle error case
      print("Invalid question index");
      return;
    }

    if (answers[index] == null || answers[index].isEmpty) {
      print("Answer is empty");
      return;
    }

    _showResult = true;
    _timer.cancel(); // Stop timer when result shown
  }

  @override
  Widget build(BuildContext context) {
    return Scaffold(
      appBar: AppBar(title: Text(widget.title)),
      body: Column(
        children: [
          Expanded(child: SingleChildScrollView(physics: NeverScrollableScrollPhysics(), child: Column(children: <Widget>[
            ...questions.map((question, index) {
              return ListTile(
                title: Text(question),
                trailing: Container(),
                onTap: () {
                  _handleButtonPress(index);
                },
                dense: true,
                leading: Icon(Icons.question_mark),
                // Ensure accessibility
                semanticLabel: '${question} · ${answers[index]}'
              );
            }))
          ])),
          Center(
            child: ElevatedButton(
              onPressed: _showResult ? null : () => _startTimer(),
              child: Text(_showResult ? 'Done' : 'Start')
            )
          )
        ]),
      ),
    );
  }
}

