        await fs.readdirSync('lib/', { recursive: true });
        const files = fs.readdirSync('lib/');
        const archives = [];

        for (const file of files) {
            if (file.endsWith('.tar')) {
                archives.push(file);
            }
        }

        console.log(`Found ${archives.length} archive(s)`);

        for (const arch of archives) {
            const sourcePath = path.join('lib/', arch);
            const destPath = path.join('dist/archives', arch);

            // Remove existing directory if it exists
            try {
                fs.rmdirSync(destPath, { recursive: true });
            } catch (err) {
                // Directory doesn't exist, so do nothing
            }

            // Copy the archive file
            fs.copyFileSync(sourcePath, destPath);
        }
    } catch (err) {
        console.error('Error copying archives:', err);
    }
};

copyArchives();
