class Produk{
    public float harga_jual;
    public boolean in_stock;
}

class Mahasiswa {
    private int nim;
    private String nama;
    private float ipk;
    private List<Produk> koleksi_produk = new ArrayList<>();

    public void tambahkanProduk(Produk produk) {
        koleksi_produk.add(produk);
    }

    public void tampilkanDaftarProduk() {
        System.out.println("Daftar Produk yang Dimiliki Mahasiswa:");
        for (Produk produk : koleksi_produk) {
            if (produk.in_stock) {
                System.out.println("- " + produk.nama + " (ID: " + produk.harga_jual + ")");
            }
        }
    }
}

public class Main {
    public static void main(String[] args) {
        // Create two products
        Produk makanan = new Produk();
        makanan.harga_jual = 15000;
        makanan.in_stock = true;

        Produk buku = new Produk();
        buku.harga_jual = 8000;
        buku.in_stock = true;

        // Add products to the student's collection
        Mahasiswa mahasiswa = new Mahasiswa();
        mahasiswa.tambahkanProduk(makanan);
        mahasiswa.tambahkanProduk(buku);

        // Display the products the student owns
        mahasiswa.tampilkanDaftarProduk();
    }
}
